import os
import json
from typing import Optional


AHCLAUDE_DIR = os.path.expanduser("~/.ahdev")
MODEL_CONFIG_FILE = os.path.join(AHCLAUDE_DIR, "model_config.json")


def ensure_ahclaude_dir():
    if not os.path.exists(AHCLAUDE_DIR):
        os.makedirs(AHCLAUDE_DIR)


def load_model_config() -> dict:
    if not os.path.exists(MODEL_CONFIG_FILE):
        return {}
    try:
        with open(MODEL_CONFIG_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    except (json.JSONDecodeError, IOError):
        return {}


def save_model_config(config: dict):
    ensure_ahclaude_dir()
    with open(MODEL_CONFIG_FILE, 'w', encoding='utf-8') as f:
        json.dump(config, f, ensure_ascii=False, indent=2)


def get_model_name() -> str:
    config = load_model_config()
    return config.get("model_name", "")


def get_api_token() -> str:
    config = load_model_config()
    return config.get("api_token", "")


def set_model_config(model_name: str, api_token: str, models: Optional[list] = None):
    config = {
        "model_name": model_name,
        "api_token": api_token,
        "models": list(models) if models else [],
    }
    save_model_config(config)


if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description="模型配置管理")
    subparsers = parser.add_subparsers(dest="command", help="子命令")

    subparsers.add_parser("get", help="获取当前模型配置")

    parser_set = subparsers.add_parser("set", help="设置模型配置")
    parser_set.add_argument("--model", type=str, required=True, help="模型名称")
    parser_set.add_argument("--token", type=str, required=True, help="API Token")
    parser_set.add_argument("--models", type=str, help="可用模型列表，逗号分隔")

    args = parser.parse_args()

    if args.command == "get":
        config = load_model_config()
        if config:
            print(f"当前模型: {config.get('model_name', 'N/A')}")
            print(f"API Token: {config.get('api_token', 'N/A')[:10]}..." if config.get('api_token') else "API Token: N/A")
            print(f"可用模型: {', '.join(config.get('models', []))}")
        else:
            print("暂无模型配置")
    elif args.command == "set":
        models = args.models.split(",") if args.models else []
        set_model_config(args.model, args.token, models)
        print(f"模型配置已保存: {args.model}")
    else:
        parser.print_help()
